// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(address caller, address to, uint256 amount) public {
        vm.assume(caller != to);
        vm.assume(caller != address(c) && to != address(c));

        vm.prank(caller);
        c.supplyTokenTo(amount, to);

        // General rule: supplying on behalf of a distinct beneficiary never changes
        // the CALLER's own credit balance in c.imBalances. The reference credits
        // only `to`; the mutant credits msg.sender, growing the caller's balance.
        assertTrue(c.imBalances(caller) == 0);
    }
}

